const cleanToolNames={'floor-sign':'Wet-floor / safety sign','trash-bag':'Waste bag',cloth:'Cleaning cloth',broom:'Broom',mop:'Mop',hands:'Organize by hand',gloves:'Cleaning gloves',refills:'Soap & paper refills',sink:'Wash at sink',labels:'Shelf labels',inspection:'Inspection checklist',gate:'Secure pen gate',bedding:'Clean bedding'};
function cleanRoom(key){const s=state(),r=s.rooms[key]||s.rooms.supply;if(!cleanDraft||cleanDraft.room!==key)cleanDraft={room:key,steps:[]};const steps=C.cleaning[key]||C.cleaning.supply,next=steps[cleanDraft.steps.length];return '<section class="card"><div class="row spread"><div><p class="eyebrow">Room care · '+esc(key)+'</p><h3>'+(!r.mess?'Clean room · practice a check':'Cleaning needed · '+r.mess+' mess marker(s)')+'</h3></div><button class="quiet" data-ui="inspect-room" data-key="'+key+'">Inspect room</button></div><p>Last cleaning: '+(r.cleanedAt?time(r.cleanedAt)+' by '+esc(r.cleanedBy):'Opening preparation')+'. Restroom checks are scheduled every '+s.day.cleanInterval+' simulated minutes during a shift.</p>'+(!r.mess?'<button class="accent" data-ui="practice-mess" data-key="'+key+'">Start a cleanup training task</button>':'')+'<div class="progress">'+steps.map((_,i)=>'<span class="'+(i<cleanDraft.steps.length?'done':'')+'"></span>').join('')+'</div>'+(next?'<h3>'+esc(C.cleanLabels[next])+'</h3><p>Pick the tool you would use for this step.</p><div class="clean-tools">'+Object.keys(cleanToolNames).map(id=>'<button data-clean-tool="'+id+'" class="tool"><span class="tool-art">'+toolImage(id==='sink'?'sink':id==='cloth'||id==='refills'?'box':'hands')+'</span>'+esc(cleanToolNames[id])+'</button>').join('')+'</div>':'<div class="success">The routine is complete. Save your final inspection.</div><button data-ui="finish-clean" data-key="'+key+'">Save cleaning & inspection ✓</button>')+'<details class="help"><summary>Show the room-cleaning routine</summary><ol>'+steps.map(t=>'<li>'+esc(C.cleanLabels[t])+'</li>').join('')+'</ol></details></section>';}
function supplies(){const s=state(),deliveries=s.deliveries.filter(d=>!d.received);return '<section class="card"><div class="row spread"><h3>'+ (TIRE?'Parts and tires':'Supply room')+' · receiving desk</h3><button data-ui-view="inventory">Order more supplies →</button></div><p>Count deliveries, compare the receipt and choose the right shelf. Food, refrigerated ingredients and cleaning supplies have different storage areas.</p>'+(deliveries.length?'<div class="queue">'+deliveries.map(d=>'<article class="ticket"><h3>'+esc(SHOP.stock[d.item].name)+'</h3><p>'+d.packs+' pack(s) · receipt says '+d.units+' '+esc(SHOP.stock[d.item].unit)+'</p><label>Count the units<input data-receive-count="'+d.id+'" type="number" min="0" value=""></label><label>Put away in<select data-receive-storage="'+d.id+'"><option value="">Choose a shelf</option>'+['Dry pantry','Refrigerated pantry','Supply room','Parts rack'].map(x=>'<option>'+x+'</option>').join('')+'</select></label><button data-receive="'+d.id+'">Count, label & put away</button></article>').join('')+'</div>':'<p class="success">All received deliveries are put away.</p>')+'</section>'+cleanRoom('supply');}
function pantry(){const s=state(),keys=Object.keys(SHOP.stock).filter(k=>C.expectedStorage(s,k)!=='Supply room');return '<section class="card"><div class="row spread"><h3>Pantry dates & stock rotation</h3><button data-ui-view="inventory">Order ingredients →</button></div><p>Check dates and package condition. Remove damaged or expired stock, then put older usable stock at the front. Count and shelve new deliveries in the supply room.</p><div class="grid">'+keys.map(k=>{const p=s.pantry[k]||{};return '<article class="stock-card '+(p.expired?'low':'')+'"><p class="eyebrow">'+esc(C.expectedStorage(s,k))+'</p><h3>'+esc(SHOP.stock[k].name)+'</h3><p><b>'+C.available(s,k)+'</b> usable · '+(s.stock[k]||0)+' total</p><p class="small">'+(p.expired?p.expired+' damaged / expired practice units':p.checked?'Date & condition checked':'Date check due')+'</p><div class="row"><button class="quiet" data-pantry="check" data-key="'+k+'">Check</button><button class="quiet" data-pantry="rotate" data-key="'+k+'">Rotate</button>'+(p.expired?'<button class="danger" data-pantry="discard" data-key="'+k+'">Discard expired</button>':'')+'</div></article>';}).join('')+'</div></section>'+supplies();}
function pens(){const s=state(),pets=s.orders.filter(o=>o.pets&&!['done','cancelled'].includes(o.status)).flatMap(o=>o.pets.map((p,i)=>({o,p,i})));return '<section class="card"><div class="row spread"><h3>Separate animal pens</h3><button data-ui-view="care">Open all animal care cards →</button></div><div class="pen-grid">'+(pets.length?pets.map(({o,p,i},n)=>'<article class="pen"><div class="pen-bars"><span>'+C.SPECIES[p.species]+'</span></div><h3>Pen '+(n+1)+' · '+esc(p.name)+'</h3><p>'+esc(p.species)+' · '+(p.done.includes('clean')?'Bedding & bowls checked':'Cleaning task waiting')+'</p><button data-ui="pet-card" data-order="'+o.id+'" data-pet-index="'+i+'">Open this pet’s tasks →</button></article>').join(''):'<p>No animals are staying yet. Create a training booking or start a practice shift when ready.</p>')+'</div></section>'+cleanRoom('pens');}
function shiftView(){const s=state(),d=s.day,minute=d.minute||0;return '<p class="eyebrow">Eight-hour work simulation</p><h2>'+(d.active?'The shop is open for practice.':'Prepare today. Open when you choose.')+'</h2><div class="shift-clock"><span>SIMULATED SHIFT</span><b id="sim-clock">'+Math.floor(minute/60)+'h '+String(minute%60).padStart(2,'0')+'m / 8h</b><div class="progress"><span class="done" style="flex:'+Math.max(1,minute)+'"></span><span style="flex:'+Math.max(1,480-minute)+'"></span></div><small id="real-clock">'+(d.active?'Real time remaining: '+Math.max(0,Math.ceil((d.startedAt+d.duration*1000-Date.now())/1000))+' seconds':'No customer arrivals in preparation mode')+'</small></div>'+(d.active?'<div class="notice">Customers keep arriving, stock is used and rooms need repeated cleaning. Assigned employees work automatically according to their demonstrated interview habits. Supervise their work and step in when necessary.</div><div class="row"><button data-ui-view="staff">Supervise employees</button><button class="quiet" data-ui-view="register">Register queue</button><button class="quiet" data-ui-view="rooms">Check rooms</button><button class="danger" data-ui="end-day">Finish this shift early</button></div>':'<section class="card"><h3>Start only when your class is ready.</h3><p>Today you can interview, train, practice baking, clean rooms, check inventory and learn the bank with customers off.</p><div class="row"><label>Eight-hour shift runs in<select id="shift-duration"><option value="300">5 real minutes</option><option value="600">10 real minutes</option></select></label><label>Restroom check every<select id="clean-interval"><option value="60">60 simulated minutes</option><option value="30">30 simulated minutes</option></select></label></div><button data-ui="start-day">Start the practice shift & customer arrivals</button><p class="small">Daily bill amounts and the $10/hour employee wage are classroom assumptions, not quoted local rates.</p></section>')+'<div class="grid">'+['lobby','restroom','supply',PET?'pens':TIRE?'garage':'pantry'].map(key=>'<section class="card"><p class="eyebrow">Room check</p><h3>'+esc(key)+'</h3><p>'+(s.rooms[key].mess?'Cleaning / organization needed':'Clean at last check')+'</p><button class="quiet" data-room-go="'+(key==='lobby'&&CAFE?'right':key)+'">Go to room →</button></section>').join('')+'</div>'+issuesView();}
function localHires(){const found=[];try{const data=JSON.parse(localStorage.getItem('ttBusinessInterviews_'+SHOP.id+'_v1')||'null');for(const[id,r]of Object.entries(data?.interviews||{}))if(r.decision==='Hired'){const original=id.replace(/-short$/,'');if(window.TTShopStaff[SHOP.id+':'+original]&&!found.includes(original))found.push(original);}}catch{}return found;}
async function loadHires(){if(hireLoad)return;hireLoad=true;try{hires=A.shared?(await A.request({action:{type:'hires'}})).hires.map(h=>h.applicant_id):localHires();if(A.view==='staff')A.render();}catch{hires=localHires();A.toast('Shared hiring results could not load. Use the interview device or retry after connecting.');}finally{hireLoad=false;}}
function staffView(){const s=state(),ids=[...new Set(hires.concat(A.shared?[]:localHires()))];return '<p class="eyebrow">Hiring has consequences · supervised work</p><h2>Your employees. Their work habits.</h2><p>The employee’s interview answers carry into the simulation: careful workers usually complete the job, developing workers need coaching, and workers who dismiss instructions need frequent supervision. Judge the work you see; coach or take over when needed.</p><div class="row"><button data-ui="interviews">Interview & hire applicants</button><button class="quiet" data-ui="load-hires">Load hired applicants</button></div><div class="grid">'+(ids.length?ids.map(id=>{const p=window.TTShopStaff[SHOP.id+':'+id],e=s.staff[id];return '<section class="card role-card"><p class="eyebrow">Hired after interview</p><h3>'+esc(p.name)+'</h3><p>'+esc(p.job)+'</p><p class="small">'+esc(p.experience)+'</p><label>Work station<select data-staff-station="'+id+'">'+['Cashier',CAFE?'Food Preparation':PET?'Animal Care':'Technician','Inventory','Cleanup'].concat(PET?['Check-in']:[]).map(st=>'<option '+(e?.station===st?'selected':'')+'>'+st+'</option>').join('')+'</select></label><button data-staff-assign="'+id+'">'+(e?'Update work assignment':'Assign this hired employee')+'</button>'+(e?'<p class="pill">'+(e.paused?'Supervisor needed':'Assigned: '+esc(e.station))+'</p><p>Wages earned '+money(e.earned)+' · paid '+money(e.paid)+'</p>'+(e.paused?'<button class="quiet" data-staff-resume="'+id+'">Return to assigned work</button>':''):'')+'</section>';}).join(''):'<section class="empty"><h3>No hired applicants loaded.</h3><p>Complete an interview and choose Hire, then load the results here. The class can practice every station themselves while preparing.</p></section>')+'</div>'+issuesView()+'<section class="card"><h3>What the supervisor is checking</h3><p>Order accuracy, following recipes or care cards, safe routines, cleaning, restocking, customer communication and reporting a problem. Employee actions are labeled as automated employee work in the data report; they are separate from student actions.</p></section>';}
function issuesView(){const s=state(),issues=s.issues.filter(i=>!i.resolved);return '<section class="card pink"><h3>Supervisor check-ins · '+issues.length+' waiting</h3>'+(issues.length?issues.map(i=>'<article class="ticket"><h3>'+esc(i.name)+' · '+esc(i.station)+'</h3><p>'+esc(i.message)+'</p><label>What direction or help will you give?<textarea data-coach-note="'+i.id+'" maxlength="300" placeholder="Explain the correction or the task you are taking over."></textarea></label><div class="row"><button data-coach="'+i.id+'" data-mode="coach">Coach & retry</button><button class="quiet" data-coach="'+i.id+'" data-mode="takeover">I will take over this task</button></div></article>').join(''):'<p>No employee problems are waiting for a supervisor.</p>')+'</section>';}
function bank(){const s=state(),f=s.finance,p=C.profit(s),bills=s.bank.bills.filter(b=>!b.paid);return '<p class="eyebrow">Transition Town Bank · business accounts</p><h2>'+esc(SHOP.name)+' business account</h2><label class="no-print">Choose a business<select id="bank-shop">'+Object.values(window.TTShopCatalog).map(shop=>'<option value="'+shop.id+'" '+(SHOP.id===shop.id?'selected':'')+'>'+esc(shop.name)+'</option>').join('')+'</select></label><div class="bank-cards"><article class="bank-card"><span>BUSINESS CHECKING</span><h3>'+esc(SHOP.name)+'</h3><b>'+money(s.cash)+'</b><small>Money available to pay suppliers, bills and wages</small></article><article class="bank-card savings"><span>BUSINESS SAVINGS</span><h3>Set money aside</h3><b>'+money(s.bank.savings)+'</b><small>Transfer it back to checking when needed</small></article></div><details class="help" open><summary>How to use your business bank</summary><ol><li>Check the business name above. Its money is separate from your personal Transition Town money.</li><li>In a shared class, connect every device to the same classroom code. Solo practice saves separately for this profile.</li><li>Customer payments at the register go into this business’s checking account. They are <b>sales</b>.</li><li>Order supplies from Inventory. The money leaves checking. Count and shelve the delivery before using it.</li><li>Open Bills to pay the shop’s lights, phone and other costs. Pay employees for the simulated hours they worked.</li><li>Move checking money to savings when you want to set some aside. A transfer is not new profit.</li><li>After reserving unpaid bills and wages, use Owner pay to transfer money to an owner’s pay account.</li><li>Read the profit calculation below. Money spent buying stock and money spent <em>using</em> stock are different: unused stock is still an asset.</li></ol><button class="quiet no-print" data-ui="read-bank">🔊 Read the banking instructions</button></details><section class="card"><p class="eyebrow">Sales are the start of the calculation</p><h3>What is our profit?</h3><div class="profit-equation"><div><small>Customer sales</small><b>'+money(f.revenue)+'</b></div><span>−</span><div><small>Ingredients / supplies used</small><b>'+money(f.cogs)+'</b></div><span>−</span><div><small>Wages earned</small><b>'+money(f.wages)+'</b></div><span>−</span><div><small>Bills, waste & training</small><b>'+money(f.overhead+f.waste+f.training)+'</b></div><span>=</span><div class="'+(p<0?'loss':'profit')+'"><small>'+(p<0?'Loss so far':'Profit so far')+'</small><b>'+money(p)+'</b></div></div><p>Profit is sales minus the costs of earning those sales. Inventory purchases lower cash immediately; the portion used becomes a cost. Owner pay ('+money(f.ownerDraw)+') lowers business cash and does not subtract from profit a second time.</p><div class="notice">Simple example: $100 sales − $30 ingredients used − $20 wages − $10 bills = <b>$40 profit</b>. Taking $15 of owner pay changes where the money is held; the profit calculation is still $40.</div></section><div class="two"><section class="card"><h3>Transfer checking ↔ savings</h3><label>Amount<input id="bank-transfer-amount" type="number" min="0" step="0.01"></label><label>Direction<select id="bank-transfer-direction"><option value="to-savings">Checking → savings</option><option value="to-checking">Savings → checking</option></select></label><button data-ui="bank-transfer">Transfer classroom money</button></section><section class="card"><h3>Owner pay</h3><p>Unpaid bills and wages to reserve: <b>'+money(C.unpaid(s))+'</b></p><label>Owner<select id="owner-pay-name">'+Object.keys(SHOP.owners).map(n=>'<option>'+esc(n)+'</option>').join('')+'</select></label><label>Amount<input id="owner-pay-amount" type="number" min="0" step="0.01"></label><button data-ui="owner-pay">Transfer to owner-pay account</button><p class="small">Owner-pay account balances: '+(Object.entries(s.bank.ownerPay).map(([n,v])=>esc(n)+' '+money(v)).join(' · ')||'No owner withdrawals yet')+'</p></section></div><section class="card"><h3>Business bills</h3><p class="small">Fictional daily allocations of rent, lights, phone, water and insurance are added only when a practice shift starts.</p>'+ (bills.length?'<div class="queue">'+bills.map(b=>'<article class="ticket"><h3>'+esc(b.name)+'</h3><p>Day '+b.day+' · '+money(b.amount)+'</p><button data-pay-bill="'+b.id+'">Pay from business checking</button></article>').join('')+'</div>':'<p>No unpaid business bills.</p>')+'</section><section class="card"><h3>Employee payroll</h3><p>Employees earn the classroom rate of $10 per simulated hour. Earned wages are an expense even while waiting to be paid.</p>'+Object.values(s.staff).map(e=>'<article class="ticket"><h3>'+esc(e.name)+'</h3><p>Earned '+money(e.earned)+' · already paid '+money(e.paid)+' · still owed <b>'+money(Math.max(0,e.earned-e.paid))+'</b></p><button data-payroll="'+e.id+'" '+(e.earned<=e.paid?'disabled':'')+'>Pay wages from checking</button></article>').join('')+'</section><section class="card"><h3>Money accounted for · register check</h3><p>Cash customer sales: '+money(s.orders.filter(o=>o.paid&&!o.training&&o.method==='Cash').reduce((n,o)=>n+o.total,0))+' · Card customer sales: '+money(s.orders.filter(o=>o.paid&&!o.training&&o.method==='Card').reduce((n,o)=>n+o.total,0))+'</p><label>According to the ledger, what is the current checking balance?<input id="reconcile-count" type="number" min="0" step="0.01"></label><button data-ui="reconcile">Check my accounting</button></section><section class="card"><h3>Business account ledger</h3><div style="overflow:auto"><table class="report-table"><thead><tr><th>Time</th><th>Transaction</th><th>Amount</th><th>Checking after</th><th>By</th></tr></thead><tbody>'+s.bank.ledger.slice().reverse().map(l=>'<tr><td>'+time(l.at)+'</td><td>'+esc(l.memo)+'</td><td>'+money(l.amount)+'</td><td>'+money(l.checking)+'</td><td>'+esc(l.by)+'</td></tr>').join('')+'</tbody></table></div><p class="small">Opening classroom funds: '+money(C.initial(SHOP.id).cash)+'. Startup funds are not customer sales or profit. This is mock banking; never enter actual financial account information.</p></section>';}
function bakingTools(l,prep,next){if(baking.step!==next.id){baking={step:next.id,tool:'',ingredient:'',amount:''};}const neededTools=Object.keys(TOOLNAMES),ingredients=Object.keys(SHOP.stock).filter(k=>!['cleaning-supplies','paper-soap-refills','cups','straws','cake-pop-sticks'].includes(k));return '<section class="recipe-bench"><p class="eyebrow">All your tools are on the workbench</p><div class="tool-lineup">'+neededTools.map(k=>'<button class="bench-tool '+(baking.tool===k?'selected':'')+'" data-bake-tool="'+k+'"><span>'+toolImage(k)+'</span>'+esc(TOOLNAMES[k])+'</button>').join('')+'</div>'+(next.ingredient?'<h3>Pick the ingredient</h3><div class="ingredient-lineup">'+ingredients.map(k=>'<button class="ingredient-jar '+(baking.ingredient===k?'selected':'')+'" data-bake-ingredient="'+k+'"><span class="jar" style="--jar-color:'+(/flour|sugar/.test(k)?'#f0e4c8':/milk|cream/.test(k)?'#f6f4e8':/water|ice/.test(k)?'#a1d1e2':/straw|tomato/.test(k)?'#ce6b68':/lettuce/.test(k)?'#7bad6c':'#c69b70')+'"></span>'+esc(SHOP.stock[k].name)+'</button>').join('')+'</div><h3>Measure the recipe amount</h3><div class="row">'+['1/4','1/2','1','2','3'].map(n=>'<button class="'+(baking.amount===n?'':'quiet')+'" data-bake-amount="'+n+'">'+n+' '+esc(next.unit||'portion')+'</button>').join('')+'</div>':'')+'<div class="measure-summary"><b>Recipe:</b> '+esc(next.label)+'<p>Your tool: '+esc(TOOLNAMES[baking.tool]||'not selected')+(next.ingredient?' · ingredient: '+esc(SHOP.stock[baking.ingredient]?.name||'not selected')+' · amount: '+esc(baking.amount||'not selected'):'')+'</p><button data-ui="apply-baking">'+(next.ingredient?'Measure & add to the recipe':'Use this tool for the step')+'</button></div><p class="small">The flat dry cup measures flour or sugar; the spouted jug measures liquids. All quantities here belong to the classroom practice recipe.</p></section>';}
function afterRender(){
 const s=state();if(!$('#day-mini')){const bar=document.createElement('div');bar.id='day-mini';bar.className='day-mini';bar.innerHTML='<span id="day-mini-clock"></span><button data-ui-view="day">Shift & room checks</button><button data-ui-view="bank">Business account '+money(s.cash)+'</button>';document.querySelector('.worker')?.after(bar);}
 updateClock();
 if(CAFE&&A.view==='kitchen'&&!A.prep){const el=document.createElement('div');el.className='station-background';el.innerHTML='<img src="'+R+'cool-vibes-kitchen.webp" alt="Cool Vibes baking kitchen and tools"><button data-ui="training-ticket">Create a kitchen training ticket</button>';$('#work-content').prepend(el);}
 if(PET&&A.view==='care')attachWalkMap();
 if(A.view==='training'){const el=document.createElement('section');el.className='card tint';el.innerHTML='<h3>Try the real workstation in preparation mode.</h3><p>A training ticket lets you practice without opening to customers. It does not create customer-sales revenue.</p><button data-ui="training-ticket">Create a training ticket →</button>';$('#work-content').append(el);}
 if(TIRE&&A.view==='managers'){const el=document.createElement('section');el.className='card pink';el.innerHTML='<h3>3K service prices</h3><p>Practice prices are editable because the original student menu left the amounts blank.</p><div class="grid">'+window.TTTireServices.map(x=>'<label>'+esc(x.name)+'<input data-tire-price="'+x.id+'" type="number" min="0" step="1" value="'+state().tirePrices[x.id]+'"></label>').join('')+'</div><button data-ui="save-tire-prices">Save service prices</button>';$('#work-content').append(el);}
 if(A.view==='report')enhanceReport();
}
function updateClock(){const s=state(),d=s.day,minute=d.minute||0;const text=d.active?'Practice shift · '+Math.floor(minute/60)+'h '+minute%60+'m / 8h':'Preparation mode · customers off';if($('#day-mini-clock'))$('#day-mini-clock').textContent=text;if($('#sim-clock'))$('#sim-clock').textContent=Math.floor(minute/60)+'h '+String(minute%60).padStart(2,'0')+'m / 8h';if($('#real-clock'))$('#real-clock').textContent=d.active?'Real time remaining: '+Math.max(0,Math.ceil((d.startedAt+d.duration*1000-Date.now())/1000))+' seconds':'Shift stopped · data saved';}
function showRoom(next){room=next;cleanDraft=null;A.setView('rooms');try{history.replaceState({},'',location.pathname+'?shop='+SHOP.id+'&view=rooms&room='+encodeURIComponent(room));}catch{}}
function value(id){return $(id)?.value||'';}function checked(id){return !!$(id)?.checked;}
function input(selector){return document.querySelector(selector)?.value||'';}
function compareAttempt(activity,choice,expected){A.recordAttempt(activity,choice,expected,'retry');A.toast('Check the recipe or work card and try again. '+expected);}
function action(type,extra={},done){return A.dispatch({type,...extra},done);}
function createTraining(){action('training-ticket',{item:'donut',service:'new-tire'},()=>{A.setView('register');A.toast('Training ticket ready at the register. Customers remain off.');});}
function downloadCsv(){const s=state(),rows=[['Business','Day','Simulated minute','Timestamp','Worker','Activity','Quality','Expected / instruction','Support','Automated employee/event']].concat(s.audit.map(r=>[SHOP.name,r.day,r.minute,new Date(r.at).toISOString(),r.by,r.message,r.quality||'',r.expected||'',r.support||'',r.automated?'Yes':'No']));const csv='\ufeff'+rows.map(row=>row.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download=SHOP.id+'-activity-data.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function enhanceReport(){const s=state(),el=document.createElement('section');el.className='card';el.innerHTML='<div class="row spread"><h3>Detailed data for Miss Kayla</h3><button data-ui="export-data">Download activity CSV</button></div><p>'+s.audit.filter(r=>r.by===A.actor&&!r.automated).length+' saved student actions for '+esc(A.actor)+' · '+s.audit.filter(r=>r.by===A.actor&&r.quality==='retry').length+' recorded correction attempts · '+s.audit.filter(r=>r.by===A.actor&&r.quality==='support').length+' support requests.</p><p>Automated employee work is identified separately. These records describe actions and prompts; they do not assume a student was independent or mastered a skill.</p><p><b>Profit:</b> '+money(C.profit(s))+' · Revenue '+money(s.finance.revenue)+' · supplies used '+money(s.finance.cogs)+' · wages earned '+money(s.finance.wages)+' · overhead '+money(s.finance.overhead)+'</p><div class="log">'+s.audit.slice().reverse().slice(0,180).map(r=>'<p><time>Day '+r.day+' · '+r.minute+' simulated min · '+time(r.at)+' · '+esc(r.by)+(r.automated?' · automated':'')+'</time><br>'+esc(r.message)+(r.quality?'<br><small>'+esc(r.quality)+(r.expected?' · '+esc(r.expected):'')+'</small>':'')+'</p>').join('')+'</div><p class="small">The most recent 5,000 detailed events are retained in this business workspace. Export each workday to keep its full classroom record.</p>';$('#work-content').append(el);}
const TIRETOOLS={'work-card':'Work order / final check','ppe':'Shop PPE','wheel-chocks':'Wheel chocks','vehicle-manual':'Vehicle manual','lug-wrench':'Lug wrench','jack-stands':'Approved lift & supports','inspection-light':'Inspection light','tire-machine':'Tire machine','wheel-balancer':'Wheel balancer','wheel-cart':'Wheel cart','wheel-weights':'Balancing weights','patch-kits':'Approved repair kit','leak-test':'Leak-test equipment','drain-pan':'Used-oil drain pan','oil-filters':'Specified oil filter','dipstick':'Oil level / leak check','brake-pads':'Specified brake parts','torque-wrench':'Calibrated torque wrench','tire-gauge':'Tire-pressure gauge'};
function tireTicket(o){return '<article class="ticket"><p class="eyebrow">Work order #'+o.id.slice(0,5).toUpperCase()+' · '+(o.training?'Training vehicle':'Practice customer')+'</p><h3>'+esc(o.customer)+'</h3><p>'+esc(o.vehicle)+'</p><p><b>'+esc(o.serviceName)+'</b> · '+o.qty+' tire(s)</p><p>'+esc(SHOP.stock[o.tire]?.name||o.tire)+'</p><p class="small">Practice vehicle card: cold pressure '+o.pressure+' PSI. Use vehicle-specific torque / lifting instructions and a qualified supervisor.</p>'+(o.notes?'<p class="notes">'+esc(o.notes)+'</p>':'')+'<p>Status: '+esc(o.status)+' · '+(o.paid?'Paid':'Not paid')+'</p><b>Invoice: '+money(o.total)+'</b></article>';}
function tireCustomer(){const s=state();return '<p class="eyebrow">3K Tire Shop · customer service request</p><h2>Tell the service desk what you need.</h2><p>Services are retained from the original 3K branding menu. Prices are editable classroom practice prices because the students’ price spaces were blank.</p><div class="two"><section class="card"><label>Customer / pretend name<input id="tire-customer" maxlength="50" value="Miss Kayla"></label><label>Practice vehicle<input id="tire-vehicle" maxlength="80" value="Classroom training car"></label><label>Requested service<select id="tire-service">'+window.TTTireServices.map(service=>'<option value="'+service.id+'">'+esc(service.name)+' · '+money(s.tirePrices[service.id])+'</option>').join('')+'</select></label><label>Vehicle-card tire specification<select id="tire-spec">'+Object.keys(SHOP.stock).filter(k=>k.startsWith('tire-')).map(k=>'<option value="'+k+'">'+esc(SHOP.stock[k].name)+'</option>').join('')+'</select></label><label>Number of tires<input id="tire-qty" type="number" min="1" max="4" value="1"></label><label>Customer concern / instructions<textarea id="tire-notes" maxlength="300" placeholder="Example: My tire keeps losing air. Please ask before doing additional work."></textarea></label><button data-tire-ui="create-order">Send work request to the service desk</button></section><aside><section class="card tint"><h3>Training today</h3><p>Customers are off in preparation mode. Use a training vehicle to practice the service desk, choosing a tire, the supervised service sequence and the register.</p><button data-ui="training-ticket">Create a training vehicle job</button></section></aside></div><div class="queue">'+s.orders.filter(o=>o.service&&!['done','cancelled'].includes(o.status)).map(tireTicket).join('')+'</div>';}
function tireRegister(){const s=state(),o=s.orders.find(o=>o.id===tyreSelected);if(o){return '<button class="quiet" data-tire-ui="clear">← Service desk queue</button><div class="two"><section class="card"><h2>'+(!o.authorized?'Vehicle check-in':!o.paid?'Service invoice & payment':'Return the vehicle')+'</h2>'+
 (!o.authorized?'<p>Read the requested service and vehicle card. Confirm what the customer authorized; do not add services without approval.</p><label class="check"><input id="tire-authorized" type="checkbox">I checked the request and confirmed authorized work.</label><button data-tire-ui="check-in">Create the authorized technician work order</button>':o.status==='working'?'<p class="notice">The technician is working. Complete the service sequence and final check before taking payment.</p><button data-ui-view="garage">Open the service bay →</button>':!o.paid?'<label>Ring the service<select id="tire-ring-service"><option value="">Choose service</option>'+window.TTTireServices.map(x=>'<option value="'+x.id+'">'+esc(x.name)+'</option>').join('')+'</select></label><label>Invoice tire quantity<input id="tire-ring-qty" type="number" min="1" max="4"></label><label class="check"><input id="tire-invoice-verified" type="checkbox">I matched the completed work to the invoice.</label><label>Payment method<select id="tire-pay-method"><option>Card</option><option>Cash</option></select></label><div class="row"><label>Cash given (if cash)<input id="tire-cash" type="number" step="0.01" min="0"></label><label>Change to return<input id="tire-change" type="number" step="0.01" min="0"></label></div><button data-tire-ui="pay">Take payment & print invoice</button>':'<label>Confirm the customer’s name<input id="tire-pickup-name" maxlength="50"></label><button data-tire-ui="handoff">Match customer & release vehicle</button>')+'</section><aside>'+tireTicket(o)+'</aside></div>';}
 return '<p class="eyebrow">3K front counter · Allen / service advisor</p><h2>Check in, invoice, and account for the money.</h2><div class="row"><button data-ui="training-ticket">Create training work order</button><button class="quiet" data-ui-view="customer">Customer request form</button></div><div class="queue">'+(s.orders.filter(o=>o.service&&!['done','cancelled'].includes(o.status)).map(o=>tireTicket(o)+'<button data-tire-select="'+o.id+'">Open at service desk →</button>').join('')||'<div class="empty">No work orders waiting.</div>')+'</div>';}
function vehicleArt(o,done){const removed=done.includes('remove-wheel')&&!done.includes('hand-thread'),wheel=(x,missing)=>missing?'<circle cx="'+x+'" cy="135" r="23" fill="#9ba5a6" stroke="#69797d" stroke-width="3"/><circle cx="'+x+'" cy="135" r="5" fill="#4a5559"/>':'<circle cx="'+x+'" cy="135" r="27" fill="#252c32" stroke="#131b21" stroke-width="5"/><circle cx="'+x+'" cy="135" r="16" fill="url(#metal)"/><path d="M'+(x-12)+' 135H'+(x+12)+'M'+x+' 123V147" stroke="#4c6268" stroke-width="3"/>';
 return '<div class="vehicle-stage">'+svg('<ellipse cx="235" cy="170" rx="170" ry="13" fill="#0002"/><path d="M44 126L61 86L143 75L187 39H283L324 77L392 91L420 127V141H45Z" fill="#5f93a7" stroke="#284955" stroke-width="3"/><path d="M164 75L197 46H234V75ZM244 46H280L314 77H244Z" fill="#c6e3e8" stroke="#33545e" stroke-width="3"/>'+wheel(120,false)+wheel(344,removed)+(done.includes('support')?'<path d="M81 163V181H151V163M303 163V181H373V163" stroke="#d55a48" stroke-width="8" fill="none"/>':'')+(removed?'<circle cx="430" cy="181" r="22" fill="#242b2f" stroke="#12181d" stroke-width="5"/>':'')+'<path d="M60 110H86M374 108H401" stroke="#fff2bd" stroke-width="6"/>','0 0 480 220')+'</div>';}
function tireGarage(){const s=state(),o=s.orders.find(o=>o.id===tyreSelected&&o.service);if(o&&o.status==='working'){const steps=C.tireRecipe(o),next=steps[tyreSteps.length],choices=Object.keys(TIRETOOLS).concat(Object.keys(SHOP.stock).filter(k=>k.startsWith('tire-')));return '<button class="quiet" data-tire-ui="clear">← Work bay queue</button><div class="two"><section class="card"><p class="eyebrow">Nick’s technician work bay · virtual service training</p><h2>'+esc(o.serviceName)+'</h2>'+vehicleArt(o,tyreSteps)+'<div class="progress">'+steps.map((_,i)=>'<span class="'+(i<tyreSteps.length?'done':'')+'"></span>').join('')+'</div>'+(next?'<h3>'+esc(next.label)+'</h3><p>Use the vehicle card and choose the right tool or matching tire from the rack.</p><div class="tool-lineup">'+choices.map(k=>'<button class="bench-tool" data-tire-tool="'+k+'"><span>'+toolImage(k.startsWith('tire-')?'donut-cutter':k==='lug-wrench'||k==='torque-wrench'?'tongs':'hands')+'</span>'+esc(TIRETOOLS[k]||SHOP.stock[k].name)+'</button>').join('')+'</div>':'<label>Set the cold tire pressure from the practice door placard<input id="tire-pressure" type="number" min="0" max="100" value="'+esc(tyrePressure)+'"></label><label class="check"><input id="tire-final-supervisor" type="checkbox">The qualified supervisor completed the final check in this simulated work order.</label><button data-tire-ui="finish-service">Save the completed service & final check</button>')+'<details class="help"><summary>Vehicle-specific service sequence</summary><ol>'+steps.map(x=>'<li>'+esc(x.label)+'</li>').join('')+'</ol></details><p class="small">This is a classroom simulation. Work on an actual vehicle requires qualified supervision and the manufacturer’s lifting, torque, tire, fluid and repair instructions.</p></section><aside class="sticky-ticket">'+tireTicket(o)+'</aside></div>';}
 const q=s.orders.filter(o=>o.service&&o.status==='working');return '<p class="eyebrow">3K Tire Shop · service bay</p><h2>Read the card. Select the parts. Follow the sequence.</h2><div class="station-background"><img src="assets/student-businesses/3k-tire-shop-interior.webp" alt="Approved 3K work bay"></div><div class="row"><button data-ui-view="register">Service desk & register</button><button class="quiet" data-ui="training-ticket">Create training vehicle</button></div><div class="queue">'+(q.length?q.map(o=>tireTicket(o)+'<button data-tire-select="'+o.id+'">Work this technician job →</button>').join(''):'<div class="empty">The service desk must check in and authorize a vehicle before work starts.</div>')+'</div>'+cleanRoom('garage');}
function attachWalkMap(){const care=A.care,o=A.currentOrder();if(!care||care.task!=='walk'||!o?.pets)return;const p=o.pets[care.pet],yard=document.querySelector('.animal-yard');if(!yard)return;const key=o.id+':'+care.pet;if(attachWalkMap.key!==key){walkPoint={x:70,y:250};attachWalkMap.key=key;}yard.className='dog-walk-board';yard.id='dog-walk-board';yard.tabIndex=0;yard.setAttribute('role','application');yard.setAttribute('aria-label','Drag the handler and dog along the sidewalk to the park and back, or use arrow keys.');
 yard.innerHTML='<svg viewBox="0 0 540 340" id="dog-walk-map" aria-label="Transition Town dog-walk route"><defs><linearGradient id="grass" x2="0" y2="1"><stop stop-color="#accf89"/><stop offset="1" stop-color="#759f61"/></linearGradient></defs><rect width="540" height="340" rx="20" fill="url(#grass)"/><path d="M35 280H500M225 280V220L340 65H490" fill="none" stroke="#596c72" stroke-width="55"/><path d="M35 280H500M225 280V220L340 65H490" fill="none" stroke="#f4df9d" stroke-width="2" stroke-dasharray="12 12"/><path d="M70 250H230L340 90L450 120V250H70" fill="none" stroke="#e2d0a5" stroke-width="29" stroke-linejoin="round"/><rect x="34" y="164" width="102" height="65" rx="7" fill="#ccab78"/><path d="M25 167L86 126L145 166Z" fill="#55794f"/><rect x="72" y="191" width="27" height="38" fill="#567b5d"/><text x="85" y="182" text-anchor="middle" fill="#254b35" font-size="11" font-weight="bold">THE ZOO</text><rect x="297" y="103" width="90" height="46" rx="14" fill="#d0e8af"/><text x="341" y="127" text-anchor="middle" fill="#346346" font-size="15" font-weight="bold">PARK</text>'+[[280,180],[310,37],[425,56],[485,170],[160,160],[120,66]].map(([x,y])=>'<ellipse cx="'+x+'" cy="'+(y+20)+'" rx="22" ry="8" fill="#2f552d33"/><rect x="'+(x-3)+'" y="'+y+'" width="7" height="25" fill="#98734f"/><circle cx="'+x+'" cy="'+y+'" r="23" fill="#4f8754"/><circle cx="'+(x-7)+'" cy="'+(y-7)+'" r="15" fill="#7ead66"/>').join('')+'<rect x="465" y="112" width="14" height="22" rx="3" fill="#2e6859"/><text x="467" y="103" fill="#284c38" font-size="10">waste</text><g id="walking-pair" transform="translate('+walkPoint.x+' '+walkPoint.y+')"><ellipse cx="6" cy="8" rx="24" ry="8" fill="#1c352638"/><circle cy="-30" r="9" fill="#a36d48"/><path d="M-8-20H8L12 0H-12Z" fill="#38668e"/><path d="M-5-1L-9 11M6-1L10 11" stroke="#344555" stroke-width="6" stroke-linecap="round"/><path d="M10-13Q29-16 30-1" fill="none" stroke="#f6e19b" stroke-width="2"/><ellipse cx="34" cy="1" rx="14" ry="8" fill="#c49259"/><circle cx="45" cy="-8" r="8" fill="#d7a36e"/><path d="M40-13L39-2" stroke="#8c6038" stroke-width="5" stroke-linecap="round"/><path d="M26 6V14M39 6V14" stroke="#9c7044" stroke-width="4"/><path d="M20 0L13-8" stroke="#b78853" stroke-width="4" stroke-linecap="round"/></g></svg><div class="walk-overlay"><b id="walk-progress">'+care.route.length+' / 4 safe route stops</b><span>Hold and drag, or use arrow keys. Stay on the tan sidewalk.</span></div>'+(care.route.includes('path')&&!p.done.includes('play')?'<button data-walk-fetch="true">Play with the dog at the park</button>':'')+(care.route.includes('path')&&!care.route.includes('potty')?'<button data-walk-waste="true">Bag & dispose of waste at the park stop</button>':'');
}
function segmentDistance(p,a,b){const dx=b.x-a.x,dy=b.y-a.y,t=Math.max(0,Math.min(1,((p.x-a.x)*dx+(p.y-a.y)*dy)/(dx*dx+dy*dy)));return Math.hypot(p.x-(a.x+t*dx),p.y-(a.y+t*dy));}
function moveDog(x,y){const care=A.care;if(!care?.leashed)return;const paths=[[{x:70,y:250},{x:230,y:250}],[{x:230,y:250},{x:340,y:90}],[{x:340,y:90},{x:450,y:120}],[{x:450,y:120},{x:450,y:250}],[{x:450,y:250},{x:70,y:250}]],p={x:Math.max(30,Math.min(500,x)),y:Math.max(35,Math.min(300,y))};if(Math.min(...paths.map(([a,b])=>segmentDistance(p,a,b)))>27)return;walkPoint=p;$('#walking-pair')?.setAttribute('transform','translate('+p.x+' '+p.y+')');const next=['gate','path','potty','home'][care.route.length],target={gate:{x:70,y:250},path:{x:340,y:90},potty:{x:450,y:120},home:{x:70,y:250}}[next];if(next&&next!=='potty'&&Math.hypot(p.x-target.x,p.y-target.y)<30){A.visitWalk(next);A.recordAttempt('Dog walk route','Reached '+next+' with the dog on leash','Follow safe route','correct');if($('#walk-progress'))$('#walk-progress').textContent=care.route.length+' / 4 safe route stops';if(next==='path'){walking=false;A.render();}if(next==='home')A.toast('Dog safely returned. Save the walk on the care card.');}}
document.addEventListener('pointerdown',e=>{const board=e.target.closest('#dog-walk-board');if(!board||e.target.closest('button'))return;if(!A.care?.leashed)return A.toast('Check the collar or harness and attach the leash first.');walking=true;e.preventDefault();const rect=$('dog-walk-map').getBoundingClientRect();moveDog((e.clientX-rect.left)/rect.width*540,(e.clientY-rect.top)/rect.height*340);});
document.addEventListener('pointermove',e=>{if(!walking||!$('dog-walk-map'))return;e.preventDefault();const rect=$('dog-walk-map').getBoundingClientRect();moveDog((e.clientX-rect.left)/rect.width*540,(e.clientY-rect.top)/rect.height*340);},{passive:false});
document.addEventListener('pointerup',()=>{if(walking){walking=false;A.render();}});
document.addEventListener('keydown',e=>{if(!$('dog-walk-board')||!['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key)||['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))return;e.preventDefault();if(!A.care?.leashed)return A.toast('Attach the leash before moving.');moveDog(walkPoint.x+(e.key==='ArrowRight'?10:e.key==='ArrowLeft'?-10:0),walkPoint.y+(e.key==='ArrowDown'?10:e.key==='ArrowUp'?-10:0));});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;
 if(b.dataset.tireSelect){tyreSelected=b.dataset.tireSelect;tyreSteps=[];tyrePressure='';A.render();return;}
 if(b.dataset.tireTool){const o=state().orders.find(o=>o.id===tyreSelected),next=C.tireRecipe(o)[tyreSteps.length];if(b.dataset.tireTool!==next.tool)return compareAttempt('Tire-service sequence',TIRETOOLS[b.dataset.tireTool]||SHOP.stock[b.dataset.tireTool]?.name,next.label);tyreSteps.push(next.id);A.recordAttempt('Tire-service step',next.label,next.label,'correct');A.render();return;}
 if(b.dataset.walkWaste){if(Math.hypot(walkPoint.x-450,walkPoint.y-120)>42)return A.toast('Walk to the park waste station before cleaning up.');if(A.care.route.length===2){A.visitWalk('potty');A.recordAttempt('Dog walk','Bagged and disposed of waste at the park','Followed safe route','correct');A.render();}return;}
 if(b.dataset.walkFetch){const o=A.currentOrder(),p=o.pets[A.care.pet];return action('pet-task',{orderId:o.id,pet:A.care.pet,task:'play',safePlay:true},()=>A.toast(p.name+' enjoyed supervised play at the park.'));}
 switch(b.dataset.tireUi){
  case'create-order':action('tire-order',{customer:value('tire-customer'),vehicle:value('tire-vehicle'),service:value('tire-service'),tire:value('tire-spec'),qty:Number(value('tire-qty')),notes:value('tire-notes')});break;
  case'clear':tyreSelected=null;tyreSteps=[];A.render();break;
  case'check-in':action('tire-check-in',{orderId:tyreSelected,verified:checked('tire-authorized')});break;
  case'finish-service':{const o=state().orders.find(o=>o.id===tyreSelected);tyrePressure=value('tire-pressure');action('tire-complete',{orderId:o.id,steps:tyreSteps,tire:o.tire,pressure:tyrePressure,supervisor:checked('tire-final-supervisor')},()=>{tyreSelected=null;tyreSteps=[];A.toast('Service and final check saved. The register can now take payment.');});break;}
  case'pay':action('tire-payment',{orderId:tyreSelected,service:value('tire-ring-service'),qty:Number(value('tire-ring-qty')),confirmed:checked('tire-invoice-verified'),method:value('tire-pay-method'),tender:value('tire-cash'),change:value('tire-change')});break;
  case'handoff':action('handoff',{orderId:tyreSelected,customer:value('tire-pickup-name')},()=>{tyreSelected=null;});break;
 }
});
function garage(){return tireGarage();}
document.addEventListener('click',e=>{
 const b=e.target.closest('button');if(!b||b.disabled)return;
 if(b.dataset.uiView){A.goto(b.dataset.uiView);return;}
 if(b.dataset.roomGo){showRoom(b.dataset.roomGo);return;}
 if(b.dataset.cleanRoom){showRoom(b.dataset.cleanRoom==='lobby'&&CAFE?'right':b.dataset.cleanRoom);return;}
 if(b.dataset.cleanTool){const next=C.cleaning[cleanDraft.room][cleanDraft.steps.length],expected=cleaningTool(next);if(b.dataset.cleanTool!==expected)return compareAttempt('Room cleaning',cleanToolNames[b.dataset.cleanTool],C.cleanLabels[next]+' · '+cleanToolNames[expected]);cleanDraft.steps.push(next);A.recordAttempt('Room cleaning',C.cleanLabels[next],C.cleanLabels[next],'correct');A.render();return;}
 if(b.dataset.receive){return action('receive',{deliveryId:b.dataset.receive,quantity:Number(input('[data-receive-count="'+b.dataset.receive+'"]')),storage:input('[data-receive-storage="'+b.dataset.receive+'"]')},()=>A.toast('Delivery counted, labeled and shelved. It is ready to use.'));}
 if(b.dataset.pantry)return action('pantry',{item:b.dataset.key,operation:b.dataset.pantry});
 if(b.dataset.bakeTool){baking.tool=b.dataset.bakeTool;A.render();return;}
 if(b.dataset.bakeIngredient){baking.ingredient=b.dataset.bakeIngredient;A.render();return;}
 if(b.dataset.bakeAmount){baking.amount=b.dataset.bakeAmount;A.render();return;}
 if(b.dataset.payBill)return action('pay-bill',{billId:b.dataset.payBill});
 if(b.dataset.payroll)return action('payroll',{employee:b.dataset.payroll});
 if(b.dataset.staffAssign)return action('staff',{employee:b.dataset.staffAssign,station:input('[data-staff-station="'+b.dataset.staffAssign+'"]'),decision:'Hired'});
 if(b.dataset.staffResume)return action('resume-employee',{employee:b.dataset.staffResume});
 if(b.dataset.coach)return action('coach',{issueId:b.dataset.coach,mode:b.dataset.mode,note:input('[data-coach-note="'+b.dataset.coach+'"]')});
 switch(b.dataset.ui){
  case'interviews':location.href=SHOP.id+'.html';break;
  case'inspect-room':action('inspect-room',{room:b.dataset.key});break;
  case'practice-mess':action('practice-mess',{room:b.dataset.key});break;
  case'finish-clean':action('clean-room',{room:b.dataset.key,steps:cleanDraft.steps},()=>{cleanDraft=null;});break;
  case'training-ticket':createTraining();break;
  case'load-hires':loadHires();break;
  case'start-day':action('start-day',{duration:Number(value('shift-duration')),cleanInterval:Number(value('clean-interval'))});break;
  case'end-day':action('end-day');break;
  case'bank-transfer':action('bank-transfer',{amount:value('bank-transfer-amount'),direction:value('bank-transfer-direction')});break;
  case'owner-pay':action('owner-pay',{owner:value('owner-pay-name'),amount:value('owner-pay-amount')});break;
  case'reconcile':{const correct=C.cents(Number(value('reconcile-count')))===state().cash;A.recordAttempt('Business bank reconciliation',value('reconcile-count'),money(state().cash),correct?'correct':'retry');A.toast(correct?'The balance matches. All business money is accounted for.':'Check the latest ledger balance and try again.');break;}
  case'read-bank':A.say('Check your business name and checking balance. Customer payments are sales. Supplies, employee wages and business bills cost money. Profit is sales minus the costs used to earn those sales. Savings transfers and owner pay move money and do not create new profit.');A.recordAttempt('Bank instructions','Used read-aloud support','Banking steps','support','Read aloud');break;
  case'apply-baking':{const p=A.prep,o=A.currentOrder();if(!p||!o)return;const next=C.recipe(o.lines[p.line]).steps[p.steps.length];if(baking.tool!==next.tool||next.ingredient&&(baking.ingredient!==next.ingredient||baking.amount!==next.amount))return compareAttempt('Recipe measuring', [TOOLNAMES[baking.tool],baking.ingredient,baking.amount].filter(Boolean).join(' · '),next.label+' using '+TOOLNAMES[next.tool]);A.recordAttempt('Recipe step',next.label,next.label,'correct');baking={};A.advancePrep(next.id);break;}
  case'export-data':downloadCsv();break;
  case'save-tire-prices':{const prices={};document.querySelectorAll('[data-tire-price]').forEach(i=>prices[i.dataset.tirePrice]=Number(i.value));action('tire-prices',{prices});break;}
  case'pet-card':A.goto('care');A.selectOrder(b.dataset.order);break;
 }
});
document.addEventListener('change',e=>{if(e.target.id==='bank-shop')location.href='shop-floor.html?shop='+encodeURIComponent(e.target.value)+'&view=bank';});
function onBackground(){updateClock();if(['day','staff','bank'].includes(A.view)&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))A.render();}
window.TTShopUI={nav,views:{rooms,home:rooms,day:shiftView,staff:staffView,bank},bakingTools,afterRender,onBackground};
if(TIRE)Object.assign(window.TTShopUI.views,{garage:tireGarage,register:tireRegister,customer:tireCustomer});
if(!query.get('view'))A.setView('rooms');else A.render();
setInterval(()=>{updateClock();if(state().day.active&&!document.hidden)A.background({type:'tick'});},5000);
